import {renderDoorEditor,validateDoors,wallSegments,edgePoints,DOOR_TYPES} from './doors.js';
import * as THREE from 'three';
import {AREA_TYPES,corners,validateArea,spatialWarnings} from './spatial.js';
export function createSpatialEditor(api){let active=null,activeDoor=null;const $=s=>document.querySelector(s),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const selected=()=>active==='boundary'?api.model().boundary:api.model().areas.find(a=>a.id===active);
function selectDoor(id,redraw=true){if(!api.model().boundary.doors?.some(d=>d.id===id))return;api.prepareDoor();active='boundary';activeDoor=id;if(redraw)api.render();}
function select(id,event){api.selectArea(id,event);}
$('#boundary-edit').onclick=()=>select('boundary');document.querySelectorAll('[data-area-add]').forEach(button=>button.onclick=()=>{api.commit(()=>{const type=button.dataset.areaAdd,b=api.model().boundary,a={id:crypto.randomUUID(),type,name:AREA_TYPES[type].label+' '+(api.model().areas.filter(x=>x.type===type).length+1),x:b.x+2,y:b.y+b.depth-7,width:type==='aisle'?12:8,depth:type==='aisle'?2.5:5,rotation:0};api.model().areas.push(a);api.onAdded(a.id);});});
function render(){const m=api.model();if(activeDoor&&!m.boundary.doors?.some(d=>d.id===activeDoor))activeDoor=null;if(active&&!selected())active=null;$('#area-list').innerHTML=m.areas.map(a=>`<button class="rack-row ${api.isSelected(a.id)?'selected':''}" data-area="${a.id}"><span>${esc(a.name)}</span><small>${a.width}×${a.depth}m</small></button>`).join('');document.querySelectorAll('[data-area]').forEach(b=>b.onclick=e=>select(b.dataset.area,e));const a=selected();$('#spatial-inspector').hidden=!a;$('#rack-inspector').hidden=!!a;if(a){const boundary=active==='boundary';$('#spatial-inspector').innerHTML=`<div class="eyebrow">SPACE / 物理区域</div><h2>${activeDoor?'门属性':boundary?'仓库边界':AREA_TYPES[a.type].label}</h2><form id="area-form" ${activeDoor?'hidden':''}><div class="fields">${[['name','名称','text'],['x','X 坐标 / 米','number'],['y','Y 坐标 / 米','number'],['width','宽度 / 米','number'],['depth','深度 / 米','number'],...boundary?[]:[['rotation','旋转 / 度','number']]].map(([k,label,type])=>`<label class="${k==='name'?'wide':''}">${label}<input name="${k}" type="${type}" step="any" value="${esc(a[k])}" required></label>`).join('')}</div><p class="muted">面积 ${(a.width*a.depth).toFixed(1)} m² · 不属于任何 FG<br>${boundary?'修改边界不会移动内部货架。':'拖动区域可移动；右下角手柄可调整大小。'}</p><div class="field-actions"><button class="primary">应用修改</button>${boundary?'':'<button type="button" id="area-delete" class="danger">删除区域</button>'}<button type="button" id="back-rack">返回货架</button></div></form>${boundary?'<div id="door-editor"></div>':''}`;if(boundary)renderDoorEditor($('#door-editor'),a,{...api,onDoorSelect:selectDoor},esc,activeDoor);$('#area-form').onsubmit=e=>{e.preventDefault();api.commit(()=>{const next={...a};for(const [k,v]of new FormData(e.target))next[k]=k==='name'?v.trim():Number(v);validateArea(next,boundary);if(boundary)validateDoors(next);Object.assign(a,next);});};$('#back-rack').onclick=()=>{active=null;api.render();};if(!boundary)$('#area-delete').onclick=()=>api.commit(()=>{m.areas=m.areas.filter(x=>x.id!==a.id);active=null;});}
const warnings=spatialWarnings(m);$('#spatial-checks').innerHTML=`<h3>布局检查 <span>${warnings.length?warnings.length+' 项提示':'通过'}</span></h3>${warnings.length?warnings.slice(0,12).map(w=>`<button class="warning-row" data-warning="${w.id}">${esc(w.text)}</button>`).join('')+(warnings.length>12?`<p class="muted">另有 ${warnings.length-12} 项，请先处理以上提示。</p>`:''):'<p class="muted">无越界、货架占用通道或暂存区。</p>'}`;document.querySelectorAll('[data-warning]').forEach(b=>b.onclick=()=>{if(m.areas.some(x=>x.id===b.dataset.warning))select(b.dataset.warning);else{active=null;api.selectRack(b.dataset.warning);}});
}
function draw2d(layer,unit){const m=api.model(),b=m.boundary;const boundary=new Konva.Rect({x:b.x*unit,y:b.y*unit,width:b.width*unit,height:b.depth*unit,fill:'#ffffff60'});boundary.setAttr('cadBackground',true);layer.add(boundary);for(const points of wallSegments(b)){const line=new Konva.Line({points:points.flatMap(p=>[p.x*unit,p.y*unit]),stroke:active==='boundary'?'#b59646':'#9aabb7',strokeWidth:active==='boundary'?3:2,dash:[10,5]});line.setAttr('cadBackground',true);layer.add(line);}for(const d of b.doors||[]){const [p,q]=edgePoints(b,d.side,d.offset,d.offset+d.width),g=new Konva.Group({name:'boundary-door'});const padding=12/layer.getStage().scaleX();g.add(new Konva.Rect({x:Math.min(p.x,q.x)*unit-padding,y:Math.min(p.y,q.y)*unit-padding,width:Math.abs(q.x-p.x)*unit+padding*2,height:Math.abs(q.y-p.y)*unit+padding*2,fill:'rgba(255,255,255,0.001)'}));g.add(new Konva.Line({name:'door-line',points:[p.x*unit,p.y*unit,q.x*unit,q.y*unit],stroke:activeDoor===d.id?'#b28b35':DOOR_TYPES[d.type].color,strokeWidth:activeDoor===d.id?10:8,hitStrokeWidth:Math.max(18,22/layer.getStage().scaleX()),dash:[5,3]}));for(const v of [p,q])g.add(new Konva.Circle({x:v.x*unit,y:v.y*unit,radius:3,fill:'#758f9e'}));g.add(new Konva.Text({x:(p.x+q.x)/2*unit-50,y:(p.y+q.y)/2*unit+(d.side==='top'?-20:8),width:100,text:d.name+' · '+d.width+'m',align:'center',fontSize:12,fill:'#546e7d'}));g.on('click tap',e=>{e.cancelBubble=true;if(!api.isPanning())selectDoor(d.id);});api.bindDoor(g,d,b,()=>selectDoor(d.id,false));layer.add(g);}layer.add(new Konva.Text({x:b.x*unit,y:(b.y-.8)*unit,text:`${b.name} · ${b.width.toFixed(1)} × ${b.depth.toFixed(1)} m`,fontSize:12,fill:'#6f8391',listening:false}));for(const a of m.areas){const colors=AREA_TYPES[a.type],g=new Konva.Group({x:a.x*unit,y:a.y*unit,rotation:a.rotation,draggable:true});g.add(new Konva.Rect({width:a.width*unit,height:a.depth*unit,fill:colors.color,opacity:.8,stroke:api.isSelected(a.id)?'#996c27':colors.stroke,strokeWidth:api.isSelected(a.id)?3:1.5,dash:a.type==='aisle'?[8,4]:undefined}));g.add(new Konva.Text({x:6,y:6,width:Math.max(20,a.width*unit-12),text:`${a.name}\n${a.width} × ${a.depth} m`,fontSize:12,lineHeight:1.5,fill:'#576872',listening:false}));if(a.type==='aisle')g.add(new Konva.Line({points:[8,a.depth*unit/2,a.width*unit-8,a.depth*unit/2],stroke:colors.stroke,dash:[12,8],opacity:.5,listening:false}));api.bindArea(g,a);if(active===a.id){const handle=new Konva.Rect({x:a.width*unit-5,y:a.depth*unit-5,width:10,height:10,fill:'#fff',stroke:'#996c27',strokeWidth:2,draggable:true});api.bindResize(handle,a);g.add(handle);}layer.add(g);}}
function label(parent,a){const canvas=document.createElement('canvas');canvas.width=768;canvas.height=128;const c=canvas.getContext('2d');c.font='40px "Microsoft YaHei", sans-serif';c.textAlign='center';c.fillStyle='#435967';c.fillText(a.name,384,64);const texture=new THREE.CanvasTexture(canvas),sprite=new THREE.Sprite(new THREE.SpriteMaterial({map:texture,depthTest:false,transparent:true}));sprite.position.set(a.x+Math.cos(a.rotation*Math.PI/180)*a.width/2-Math.sin(a.rotation*Math.PI/180)*a.depth/2,.35,a.y+Math.sin(a.rotation*Math.PI/180)*a.width/2+Math.cos(a.rotation*Math.PI/180)*a.depth/2);sprite.scale.set(7,1.17,1);parent.add(sprite);}
function draw3d(world,box){const m=api.model(),b=m.boundary;box(world,b.width,.025,b.depth,b.x+b.width/2,-.06,b.y+b.depth/2,'#f9fbfc');for(const [p,q]of wallSegments(b))box(world,Math.max(.1,Math.abs(q.x-p.x)),.1,Math.max(.1,Math.abs(q.y-p.y)),(p.x+q.x)/2,0,(p.y+q.y)/2,'#9aabb7',{areaId:'boundary'});for(const d of b.doors||[]){const [p,q]=edgePoints(b,d.side,d.offset,d.offset+d.width),color=activeDoor===d.id?'#b28b35':DOOR_TYPES[d.type].color;for(const v of [p,q])box(world,.12,2.4,.12,v.x,1.2,v.y,color,{doorId:d.id});box(world,Math.max(.12,Math.abs(q.x-p.x)),.14,Math.max(.12,Math.abs(q.y-p.y)),(p.x+q.x)/2,2.4,(p.y+q.y)/2,color,{doorId:d.id});label(world,{name:d.name,x:(p.x+q.x)/2,y:(p.y+q.y)/2,width:0,depth:0,rotation:0});}for(const a of m.areas){const g=new THREE.Group();g.position.set(a.x,-.015,a.y);g.rotation.y=-a.rotation*Math.PI/180;world.add(g);box(g,a.width,.025,a.depth,a.width/2,0,a.depth/2,AREA_TYPES[a.type].color,{areaId:a.id});for(const [x,z,w,d]of [[a.width/2,0,a.width,.06],[a.width/2,a.depth,a.width,.06],[0,a.depth/2,.06,a.depth],[a.width,a.depth/2,.06,a.depth]])box(g,w,.03,d,x,.02,z,active===a.id?'#996c27':AREA_TYPES[a.type].stroke,{areaId:a.id});label(world,a);}}
return {doorBounds(){const b=api.model().boundary,d=b.doors?.find(x=>x.id===activeDoor);if(!d)return null;const [p,q]=edgePoints(b,d.side,d.offset,d.offset+d.width);return {x:Math.min(p.x,q.x)-1,y:Math.min(p.y,q.y)-1,width:Math.abs(q.x-p.x)+2,depth:Math.abs(q.y-p.y)+2};},selectDoor,doorId:()=>activeDoor,raiseDoors(layer){layer.find('.boundary-door').forEach(n=>n.moveToTop());},setActive(id){active=id;activeDoor=null;},render,draw2d,draw3d,select,clear(){active=null;activeDoor=null;},points(){return [...corners(api.model().boundary),...api.model().areas.flatMap(corners)];}};
}
